/**
 * @name Command injection in subprocess calls
 * @description Untrusted data flowing to subprocess calls can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // os.system
      call = API::moduleImport("os").getMember("system").getACall()
      or
      // subprocess.call and similar
      call = API::moduleImport("subprocess").getMember(["call", "check_call", "check_output", "Popen", "run"]).getACall()
      or
      // os.popen and variants
      call = API::moduleImport("os").getMember(["popen", "popen2", "popen3", "popen4"]).getACall()
    |
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal vulnerability
 * @description User input flowing to file system operations can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File open operations
    exists(DataFlow::CallCfgNode call |
      // built-in open()
      call = API::builtin("open").getACall()
      or
      // os.open()
      call = API::moduleImport("os").getMember("open").getACall()
      or
      // file() constructor (Python 2)
      call = API::builtin("file").getACall()
      or
      // io.open()
      call = API::moduleImport("io").getMember("open").getACall()
      or
      // codecs.open()
      call = API::moduleImport("codecs").getMember("open").getACall()
      or
      // gzip.open()
      call = API::moduleImport("gzip").getMember("open").getACall()
      or
      // tarfile.open()
      call = API::moduleImport("tarfile").getMember("open").getACall()
      or
      // zipfile.ZipFile()
      call = API::moduleImport("zipfile").getMember("ZipFile").getACall()
      or
      // shutil operations that take file paths
      call = API::moduleImport("shutil").getMember(["copy", "copy2", "copyfile", "move", "rmtree"]).getACall()
    |
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

/**
 * @name Path traversal in archive extraction
 * @description Untrusted data flowing to archive extraction operations can lead to path traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // tarfile.extractall, tarfile.extract
      call = API::moduleImport("tarfile").getMember(["extractall", "extract"]).getACall()
      or
      // zipfile.extractall, zipfile.extract
      call = API::moduleImport("zipfile").getMember(["extractall", "extract"]).getACall()
      or
      // shutil.unpack_archive
      call = API::moduleImport("shutil").getMember("unpack_archive").getACall()
    |
      // The path/member argument (often first argument for extract methods)
      sink = call.getArg(1) or sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

